      const hay = `${clean(t.title)} ${clean(t.host)}`;
      if (words.every((w) => hay.includes(w))) rows.push({ kind: 'tab', id: t.id, title: t.title, host: t.host, sleeping: Boolean(t.sleeping), active: Boolean(t.active) });
